import pickle
from collections import defaultdict

allq = pickle.load(open('/tmp/allq.pkl','rb'))

def eval_method(fn, qs):
    correct=0
    for q in qs:
        ans = fn(q['samples'])
        if ans==q['correct_answer']:
            correct+=1
    return correct/len(qs)

def sum_per_variant_max(samples):
    # for each (answer, variant), keep only the best score
    best = defaultdict(lambda: -1e9)
    for s in samples:
        key=(s['answer'], s['variant'])
        if s['score']>best[key]:
            best[key]=s['score']
    sums=defaultdict(float)
    for (a,v), sc in best.items():
        sums[a]+=sc
    return max(sums.items(), key=lambda kv: kv[1])[0]

def sum_per_variant_mean(samples):
    sums_v=defaultdict(float); cnt_v=defaultdict(int)
    for s in samples:
        key=(s['answer'], s['variant'])
        sums_v[key]+=s['score']; cnt_v[key]+=1
    sums=defaultdict(float)
    for (a,v) in sums_v:
        sums[a]+= sums_v[(a,v)]/cnt_v[(a,v)]
    return max(sums.items(), key=lambda kv: kv[1])[0]

def sum_score(samples):
    sums=defaultdict(float)
    for s in samples: sums[s['answer']]+=s['score']
    return max(sums.items(), key=lambda kv: kv[1])[0]

print('sum_per_variant_max', eval_method(sum_per_variant_max, allq))
print('sum_per_variant_mean', eval_method(sum_per_variant_mean, allq))
print('sum_score', eval_method(sum_score, allq))
